    "influence-restriction": "influence-restriction.png",
    military: "military.png",
    "military-skill": "military-skill.png",
    "military-focus": "military-focus.png",
    "military-restriction": "military-restriction.png",
    "any-skill": "any-skill.png",
    "best-focus": "best-focus.png",
